// ===== GENTLE, RELATIONAL GOSPEL PARENTING =====
Object.assign(TYPE,{B:'Body condition',K:'Parenting'});
NEWSECS.push({id:'par',n:'Gospel Parenting',h:25,d:'Gentle, relational parenting shaped by how God parents us: what is happening behind a child\'s behaviour, do\'s and don\'ts for each age, practical help for everyday problems, and scriptures to pray and live.'});
function K(o){MAPS.push(Object.assign({type:'K',area:'par'},o,{links:sp(o.links||''),tools:(o.tools||'').split(' ').filter(Boolean)}));PLAN[o.t]=o.tools}

// ---------- age stages ----------
K({kind:'age',kid:'baby',t:'Babies (0–12 months): Building Trust',range:'0–12 months',mm:'coreg',
 brain:'A baby\'s brain doubles in size in the first year and forms more than a million new connections every second. The brainstem and emotional brain lead; the thinking brain has barely started. Babies cannot calm themselves; they borrow calm from you.',
 needs:'Safety;Warm, responsive care;Touch and closeness;Predictable rhythms;Face-to-face play',
 normal:'Crying is communication, not manipulation;Waking at night is normal;Wanting to be held constantly, especially in the first months;Stranger anxiety from around 6–9 months;Putting everything in the mouth',
 do:'Respond to crying promptly and warmly; you cannot spoil a baby with love;Hold, carry, rock and sing; rhythm calms the brainstem;Talk, smile and copy their sounds ("serve and return");Keep simple daily rhythms for feeding and sleep;Look after yourself and accept help; your calm is their calm',
 dont:'Never shake a baby, even for a moment; if overwhelmed, put the baby down safely and step away;Don\'t leave babies to cry for long periods in the early months;Don\'t expect "good behaviour"; babies can\'t yet control themselves;Avoid screens for babies under 18 months except video calls',
 problems:[['Crying that won\'t stop','Babies cry from hunger, tiredness, wind, discomfort or overstimulation; some cry more than others (colic peaks around 6 weeks).','Check basics, then try motion, white noise, swaddling (if under 2 months), skin-to-skin, or a calm walk. If you feel at breaking point, lay the baby safely in the cot and take five minutes.'],
  ['Sleep struggles','Baby sleep cycles are short and night waking is normal for months.','Keep a simple bedtime routine, dim lights, and follow safe sleep guidance (on the back, own cot, no loose bedding). Share night duties when possible.'],
  ['Separation crying','From about 8 months babies understand you exist when you leave, and they protest.','Short, warm goodbyes; a consistent carer; play peek-a-boo to practise "gone and back".']],
 verse:'Isaiah 66:13|As one whom his mother comforts, so I will comfort you.',more:'Isaiah 49:15; Psalm 22:9-10; Isaiah 40:11',
 action:'Spend ten minutes of face-to-face play today with no phone nearby.',
 simple:'Babies cannot calm themselves yet. When we pick them up, feed them and talk to them kindly, their brain learns: "The world is safe and I am loved."',links:'Co-regulation: Brains Regulate Brains;Attachment Styles',tools:'hug rhythm voo'});

K({kind:'age',kid:'toddler',t:'Toddlers (1–3 years): Big Feelings, Small Brakes',range:'1–3 years',mm:'coreg',
 brain:'The emotional brain is racing ahead while the "upstairs" thinking brain is years from finished. Toddlers feel huge feelings with almost no brakes, and they are wired to explore and say "no" as they discover they are separate people.',
 needs:'Safety and connection;Freedom to explore safely;Simple, consistent limits;Words for feelings;Lots of play and movement',
 normal:'Tantrums, especially when tired or hungry;"No!" and "Me do it!";Hitting, biting or grabbing (no impulse control yet);Short attention span;Fear of separation and the dark',
 do:'Name feelings for them: "You\'re so cross the tower fell";Stay close and calm during tantrums; your calm is the lesson;Give two simple choices ("red cup or blue cup?");Childproof instead of saying "no" all day;Keep routines predictable, and warn before transitions',
 dont:'Don\'t smack or shake; it teaches that big people hit when upset;Don\'t shame ("naughty girl", "big boys don\'t cry");Don\'t reason during a meltdown; the thinking brain is offline;Don\'t expect sharing; it develops slowly from around age 3',
 problems:[['Tantrums','The emotional brain floods and the thinking brain switches off. It is not manipulation; it is overwhelm.','Stay close, keep them safe, say little, offer a hug when they\'re ready. Talk about it later, briefly.'],
  ['Hitting and biting','Toddlers have big feelings and no words or brakes yet.','Calmly block and move them: "I won\'t let you hit. You\'re angry; you can stamp your feet." Then teach gentle hands in calm moments.'],
  ['"No" to everything','Discovering they are a separate person with a will.','Fewer battles: offer choices, make it playful, and keep the few non-negotiables (safety) firm and kind.']],
 verse:'Psalm 103:13-14|Like a father has compassion on his children… For he knows how we are made. He remembers that we are dust.',more:'Isaiah 40:11; Matthew 19:14; Proverbs 22:6',
 action:'Next tantrum, say only: "I\'m here. You\'re safe. I\'ll help you," and stay close.',
 simple:'Toddlers have very big feelings and their brain\'s brakes are still being built. When we stay calm and kind, we lend them our brakes until theirs grow.',links:'Flipping Your Lid: The Hand Model;Co-regulation: Brains Regulate Brains',tools:'connect timein choices'});

K({kind:'age',kid:'preschool',t:'Preschoolers (3–5 years): Wonder, Fears and Learning Rules',range:'3–5 years',mm:'iceberg',
 brain:'Language and imagination explode. Children can start to name feelings and follow simple rules, but self-control is still fragile, especially when tired, hungry or overwhelmed. Fantasy and reality are still mixed, so fears feel very real.',
 needs:'Connection and play;Clear, simple limits;Help naming feelings;Chances to do things themselves;Reassurance about fears',
 normal:'"Why?" questions all day;Fears of the dark, monsters, dogs;Telling stories that aren\'t true (imagination, not lying);Testing limits;Sibling squabbles',
 do:'Play every day; play is how they learn and connect;Use "when-then": "When the toys are in the box, then we\'ll read";Teach feeling words and calm-down tools (breathing, a cosy corner);Praise effort specifically ("You kept trying with that puzzle");Read Bible stories and pray simply together',
 dont:'Don\'t mock fears; take them seriously and help;Don\'t give long lectures; keep it short and concrete;Don\'t compare siblings;Don\'t use God as a threat ("God will be angry with you")',
 problems:[['Whining','Often tiredness, hunger or a need for connection, said in the only voice they have left.','Get close, meet the need if you can, and model the voice: "Can you ask me in your strong voice?"'],
  ['Night fears','Imagination is growing faster than the ability to tell real from pretend.','Listen, check together, leave a night light, pray a short prayer of protection (Psalm 4:8), and stay calm and brief.'],
  ['Not listening','Their attention is absorbed in play; instructions from across the room don\'t register.','Get down to their level, touch their shoulder, make eye contact, give one short instruction, and ask them to repeat it.']],
 verse:'Deuteronomy 6:6-7|These words, which I command you today, shall be on your heart; and you shall teach them diligently to your children, and shall talk of them when you sit in your house, and when you walk by the way.',more:'Psalm 78:4; Mark 10:16; Psalm 127:3',
 action:'Spend ten minutes of child-led play today: you follow, they lead.',
 simple:'Little children learn by playing, asking and copying. Short, kind rules, lots of play and help with scary feelings make them feel safe enough to grow.',links:'Emotional Needs;Co-regulation: Brains Regulate Brains',tools:'special ecoach choices'});

K({kind:'age',kid:'school',t:'School Age (6–11 years): Competence and Belonging',range:'6–11 years',mm:'compass',
 brain:'The thinking brain is maturing, so children can plan, reason and understand fairness. Friendships, school success and fitting in matter more and more. They begin to judge themselves, and what you say about them becomes their inner voice.',
 needs:'Feeling capable;Belonging with friends and family;Fairness and clear expectations;Your interest in their world;Responsibility in small doses',
 normal:'Strong sense of fairness ("That\'s not fair!");Friendship drama;Worry about tests or making mistakes;Arguing and negotiating;Wanting to be with friends more',
 do:'Give real responsibilities (chores, choices) and let natural consequences teach;Ask about their day with specific questions ("What made you laugh today?");Teach problem-solving: "What could you try?";Praise effort and character, not just results;Pray together about real worries',
 dont:'Don\'t rescue them from every difficulty;Don\'t make your love feel conditional on grades;Don\'t mock or tease about weaknesses;Don\'t hand over a smartphone without clear limits and supervision',
 problems:[['Homework battles','Tiredness after school, difficulty getting started, or fear of failure, not laziness.','Snack and play first, then a set time and place; sit nearby; break it into small chunks; praise starting.'],
  ['Lying','Usually fear of getting in trouble or disappointing you, or wishful thinking.','Stay calm, make telling the truth safe ("I\'m glad you told me"), focus on fixing it, and avoid traps ("Did you do this?" when you already know).'],
  ['Screen time fights','Screens are designed to be hard to stop; the child\'s brakes aren\'t strong enough yet.','Agree limits together in advance, use timers and warnings, keep screens out of bedrooms, and offer appealing alternatives.']],
 verse:'Luke 2:52|And Jesus increased in wisdom and stature, and in favour with God and men.',more:'Proverbs 22:6; 1 Timothy 4:12; Colossians 3:21',
 action:'Ask your child one specific question about their day and just listen, without fixing.',
 simple:'Children this age want to feel "I can do it" and "I belong." Giving them small jobs, cheering their effort and listening to their stories help them grow strong.',links:'Self-Image;Fear of Making Mistakes;Belonging',tools:'ecoach special choices'});

K({kind:'age',kid:'preteen',t:'Preteens (11–13 years): The Body Changes Before the Brain',range:'11–13 years',mm:'iceberg',
 brain:'Puberty brings hormone surges and rapid body changes. The emotional and reward brain becomes more sensitive, while the thinking brain is still developing. Moods swing, self-consciousness soars and peers suddenly matter enormously.',
 needs:'Privacy and respect;Accurate information about bodies and puberty;Stable, warm connection even when they push away;Help with peer pressure;Room to form their own views',
 normal:'Mood swings;Embarrassment about parents;Wanting more privacy;Body worries;Questioning rules and faith',
 do:'Stay close without pushing; talk side-by-side (in the car, walking, cooking);Explain puberty and online safety before they need it;Listen more than you lecture;Keep a few clear house rules and explain the reasons;Affirm who they are, not only what they do',
 dont:'Don\'t tease about their body, crushes or moods;Don\'t take eye-rolling personally; stay the steady adult;Don\'t read their messages secretly; agree transparent rules instead;Don\'t make faith a battleground; keep the door open',
 problems:[['Moodiness and slammed doors','Hormones, tiredness and an emotional brain that reacts faster than they can explain.','Give space, then reconnect later with a snack or a drive. Name it kindly: "Rough day? I\'m here when you want to talk."'],
  ['Phone and social media','Their brain is extra sensitive to social reward and rejection.','Agree a family tech plan: phones out of bedrooms at night, age-appropriate apps, and regular check-ins about what they see.'],
  ['Body image worries','Bodies change unevenly and comparison is everywhere.','Don\'t comment on weight; talk about what bodies do; model kindness toward your own body; watch for signs of eating problems.']],
 verse:'1 Samuel 16:7|Man looks at the outward appearance, but the LORD looks at the heart.',more:'Psalm 139:13-16; 1 Timothy 4:12; Proverbs 3:5-6',
 action:'Offer a "side-by-side" activity this week (a drive, a walk, cooking) and let them choose what to talk about.',
 simple:'In these years the body changes fast and feelings go up and down like a roller coaster. Kids need parents who stay calm, kind and close, even when they want more space.',links:'Self-Image;Fear of Judgment;Belonging',tools:'ecoach kidrepair special'});

K({kind:'age',kid:'teen',t:'Teenagers (13–18 years): Roots and Wings',range:'13–18 years',mm:'compass',
 brain:'The teenage brain is being rewired: unused connections are pruned and the thinking brain is myelinated from back to front, finishing in the mid-twenties. The reward system is extra sensitive, so teens take more risks, especially with friends watching. This is a season of forming identity, not rebellion for its own sake.',
 needs:'Respect and growing independence;A safe place to come back to;Honest conversations about real issues;Guidance without control;Room to own their faith',
 normal:'Late-night energy and sleeping in (their body clock shifts later);Arguing and testing views;Risk-taking;Wanting friends more than family;Doubts and questions about God',
 do:'Shift from controlling to coaching: ask "What do you think you\'ll do?";Keep a few non-negotiables (safety, honesty, respect) and negotiate the rest;Be available late at night; that is when teens often talk;Share your own faith honestly, including your doubts and how God met you;Repair quickly after conflict',
 dont:'Don\'t lecture, nag or bring up past failures;Don\'t humiliate them in front of others;Don\'t threaten to withdraw love or kick them out;Don\'t force faith; pressure tends to push it away',
 problems:[['Arguing and back-talk','They are practising independent thinking and testing whether you will still respect them.','Stay calm, set the boundary on tone ("I want to hear you; please speak respectfully"), and take their argument seriously.'],
  ['Withdrawal','Normal need for privacy, or a sign of something deeper (depression, bullying, anxiety).','Keep showing up with low-pressure time. If withdrawal comes with hopelessness, big sleep or eating changes, or self-harm, seek help promptly.'],
  ['Risky choices','The reward brain is louder than the brakes, especially with peers.','Talk through scenarios in advance, agree a "no questions asked" pick-up code, and let them earn trust step by step.']],
 verse:'Proverbs 22:6|Train up a child in the way he should go, and when he is old he will not depart from it.',more:'Luke 15:20; 2 Timothy 1:5; Jeremiah 29:11',
 action:'Tell your teen this week: "Whatever happens, you can always call me. I\'ll come, no lecture first."',
 simple:'Teenagers are learning to be grown-ups. Their brain is still being finished. They need a parent who trusts them a little more each year and is always there if they fall.',links:'Rejection Sensitivity;Belonging;Authenticity vs. Adaptation',tools:'kidrepair ecoach dearman'});

K({kind:'age',kid:'adult',t:'Adult Children (18+): From Parent to Friend',range:'18 years and up',mm:'fence',
 brain:'The thinking brain finishes maturing in the mid-twenties. Adult children need to make their own choices, including ones you disagree with. The relationship shifts from authority to influence, from parent-in-charge to trusted counsellor and friend.',
 needs:'Respect for their decisions;A warm home they want to visit;Advice when asked, not imposed;Blessing more than control;Honest repair of past hurts',
 normal:'Different choices about career, partners, faith or lifestyle;Needing space to separate, then coming back closer;Old childhood hurts coming up;Financial and practical dependence for a while',
 do:'Ask before advising: "Would you like my thoughts?";Bless their marriage or home and let them lead it;Apologise for past mistakes when they come up;Pray for them faithfully and specifically;Keep the door open, whatever they choose',
 dont:'Don\'t use guilt, money or God\'s name to control their choices;Don\'t criticise their partner or parenting in front of them;Don\'t rescue them from every consequence;Don\'t make your love conditional on their faith or obedience',
 problems:[['They make choices I disagree with','They are adults working out their own life, sometimes in reaction to how they were raised.','Say your concern once, kindly, then: "It\'s your decision, and I love you." Keep the relationship warm.'],
  ['Old hurts come up','Healing often begins when adult children feel safe enough to name what hurt.','Listen without defending; say "I\'m sorry I hurt you. Tell me more." Repair matters more than explanations.'],
  ['Walking away from faith','Questions, hurt or seeing faith used to control can push people away.','Keep loving, keep praying, live your faith with grace, and let them see God\'s kindness in you (Luke 15).']],
 verse:'Luke 15:20|While he was still far off, his father saw him, and was moved with compassion, and ran, and fell on his neck, and kissed him.',more:'Genesis 2:24; Philippians 1:3-6; Numbers 6:24-26',
 action:'Send your adult child a message of blessing this week with no advice in it.',
 simple:'When children grow up, parents stop being the boss and become a kind friend and helper. We keep loving them, even when they choose differently from us.',links:'Controlling "Love";Care vs. Control;Repair & Reconciliation',tools:'blessing kidrepair bscript'});

// ---------- everyday parenting problems ----------
// t, ages, behind, need, now, later, long, say, dont, verse, more, action, simple, mm, tools, links
const KP=[
 ['tantrum','Tantrums and Meltdowns','1–7','The emotional brain has flooded and the thinking brain has gone offline. Hunger, tiredness, transitions and disappointment are common triggers. It is overwhelm, not manipulation.','Safety, co-regulation and comfort','Stay close and calm; keep everyone safe;Say very little: "I\'m here. You\'re safe.";Lower your voice and body; offer a hug when they\'re ready;Wait; don\'t reason or punish mid-storm','When calm, name what happened in a few words;Reconnect: a cuddle, a snack, a story;Teach one calm-down tool for next time (deep "smell the flower, blow the candle" breaths)','Spot patterns (time of day, hunger, transitions) and plan for them;Warn before transitions; use routines and visual timers;Build a cosy calm-down corner you use together','"I\'m here. You\'re safe.";"You\'re so disappointed. That\'s really hard.";"I won\'t let you hit. I\'ll keep you safe."','Smacking, shouting or threatening;Giving in to stop the storm, then resenting it;Shaming ("Stop being a baby")','Isaiah 66:13|As one whom his mother comforts, so I will comfort you.','Psalm 131:2; Isaiah 40:11; James 1:19','Plan your one calm sentence for the next meltdown and practise it today.','When a child has a big tantrum, their brain is like a storm. They need us to stay calm and close, like a lighthouse, until the storm passes.','coreg','timein connect','Flipping Your Lid: The Hand Model'],
 ['hitting','Hitting, Biting and Grabbing','1–6','Young children have big feelings and few words or brakes. Hitting is often frustration, tiredness, fear or wanting something, expressed through the body.','Safety, words for feelings, and a way to get what they need','Calmly block or move them: "I won\'t let you hit.";Check the hurt child first;Name the feeling: "You\'re angry he took your car."','Later, practise what to do instead: "Stop, say \'my turn\', or come get me.";Role-play with toys;Help them make it right (a cold cloth for the friend, a sorry when ready)','Teach feelings words daily;Keep play groups small and supervised;Notice and praise gentle hands','"I won\'t let you hit. Hands are for helping.";"You can stamp your feet or squeeze this pillow.";"Let\'s check on her together."','Hitting back "so they know how it feels";Forcing an instant, empty "sorry";Long lectures','Ephesians 4:26|Be angry, and don\'t sin.','James 1:19-20; Proverbs 15:1; Romans 12:21','Teach one "angry but safe" action today (stamping, squeezing a pillow) in a calm moment.','Little children sometimes hit because their feelings are bigger than their words. We stop the hitting kindly and teach them safe ways to show anger.','light','connect choices','Anger;The Anger Iceberg'],
 ['lying','Lying','4–16','Most lying comes from fear of punishment, wanting to please you, or protecting themselves from shame. Young children also mix imagination and reality.','Safety to tell the truth','Stay calm; avoid traps ("Did you do this?" when you know);Say what you know: "I see the vase is broken.";Make honesty safe: "Thank you for telling me the truth."','Focus on fixing: "What can we do to make it right?";Talk about trust: it grows when we tell the truth;Share a time you told the truth and it was hard','Respond to mistakes without rage, so truth is safe;Praise honesty more than you punish mistakes;Model honesty in small things','"I\'m not angry. I want to help you fix it.";"Telling the truth was brave.";"In our family we tell the truth, even when it\'s hard."','Harsh punishment that makes lying safer next time;Calling them "a liar";Lying yourself, even small lies','Ephesians 4:25|Therefore putting away falsehood, speak truth each one with his neighbour.','Proverbs 12:22; 1 John 1:9; Psalm 51:6','Next time your child confesses something, say "Thank you for telling me" before anything else.','Children often lie because they are scared of getting in trouble. If telling the truth feels safe, they learn to tell the truth.','iceberg','kidrepair connect','Guilt vs. Shame vs. Embarrassment'],
 ['defiance','Defiance and "No!"','2–16','Children push back when they need some control, when they are tired or overwhelmed, or when they feel disconnected. "Kids do well if they can": defiance often means a skill is missing, not a will is evil.','Connection, some control, clear limits','Pause and get close, at eye level;Offer two acceptable choices;State the limit calmly and follow through without anger','Ask what got in the way: "What made it hard?";Solve the problem together (Ross Greene\'s collaborative approach);Notice and name cooperation','Fewer, clearer rules, explained;Daily one-to-one time (connection reduces defiance);Give real responsibilities and choices','"You don\'t want to stop playing. It\'s still time for dinner. Do you want to walk or hop to the table?";"I hear you. The answer is still no.";"Let\'s figure this out together."','Power struggles over small things;Threats you won\'t keep;Labelling them "difficult" or "rebellious"','Proverbs 15:1|A gentle answer turns away wrath, but a harsh word stirs up anger.','Colossians 3:21; Ephesians 6:4; Galatians 6:1','Pick the one daily battle you most often lose and offer two choices instead of a command.','When children say "No!" they are often telling us they need a little control or a little closeness. Giving small choices and staying kind helps.','iceberg','choices special','Need for Control'],
 ['siblings','Sibling Fighting','2–18','Siblings compete for parents\' attention and fairness, and they practise conflict on the safest people they know. Jealousy is normal.','Fairness, individual attention, conflict skills','Stop hurting; separate if needed;Listen to each without judging who started it;Describe the problem: "Two kids, one tablet."','Coach them to solve it: "What ideas do you have?";Help repair: not forced sorry, but "What would make it right?";Talk about each child\'s feelings privately','Give each child regular one-to-one time;Don\'t compare them;Teach turn-taking, negotiation and repair','"I see two kids who both want the same thing. What can we do?";"You\'re both important to me.";"How can you make it right with your sister?"','Taking sides or always blaming the older one;Comparing ("Why can\'t you be like your brother?");Ignoring physical or emotional bullying between siblings','Psalm 133:1|See how good and how pleasant it is for brothers to live together in unity!','Genesis 4:6-7; Genesis 33:4; Romans 12:10','Give each child ten minutes of one-to-one time this week.','Brothers and sisters fight because they all want to feel loved and treated fairly. Time alone with each child and help to solve problems make home more peaceful.','repair','special kidrepair','The Hardened Heart;Repair After a Conflict'],
 ['bedtime','Bedtime Battles','2–12','Bedtime means separation from you, the end of fun, and lying alone with worries. Overtired children also get wired, not sleepy.','Connection, predictability, security','Keep calm and boring; whisper;Use the same short routine every night;Offer a comfort object and a promise to check in','Build a visual bedtime chart together;Talk about worries earlier in the evening, not at lights-out;Pray together: a short, peaceful blessing','Consistent sleep and wake times, even at weekends;No screens for an hour before bed;Plenty of daylight and activity in the day','"It\'s time for sleep. I\'ll come back to check on you in five minutes.";"You\'re safe. God watches over you while you sleep.";"I love you. See you in the morning."','Using bedroom as punishment;Long negotiations;Screens in bedrooms','Psalm 4:8|In peace I will both lay myself down and sleep, for you, LORD alone, make me live in safety.','Proverbs 3:24; Psalm 121:3-4; Numbers 6:24-26','Start a three-step bedtime routine tonight (bath, story, blessing) and keep it the same all week.','Bedtime can feel lonely or scary for children. A calm, same-every-night routine and a loving blessing help them feel safe enough to sleep.','rhythm','blessing sleep','Sleep, Movement & the Rewiring Brain'],
 ['eating','Picky Eating and Mealtime Fights','1–10','Picky eating is normal, especially from 2–6. Children are cautious with new foods, and pressure makes them more resistant.','Safety, autonomy, a relaxed table','Serve one food they usually eat with each meal;Let them decide how much to eat from what you serve;Keep mealtimes short and pleasant','Involve them in shopping and cooking;Offer new foods many times (it can take 10–15 tries);Eat together and model enjoying varied foods','Regular meal and snack times;Limit juice and snacking before meals;Seek help if there is weight loss, choking fears or very few accepted foods','"You don\'t have to eat it. It can sit on your plate.";"What colour should we try this week?";"Thank you, God, for this food."','Forcing, bribing or punishing over food;Using dessert as a reward for eating vegetables;Commenting on their body or weight','1 Timothy 4:4-5|For every creature of God is good, and nothing is to be rejected, if it is received with thanksgiving.','Acts 2:46; Matthew 6:11; Ecclesiastes 9:7','Put one new food on the table this week with no pressure at all.','Lots of children are careful about new foods. If meals are happy and nobody forces them, they slowly learn to try more.','garden','restdigest choices','Eating Under Stress'],
 ['screens','Screen Time and Gaming Battles','4–18','Screens and games are designed to be hard to stop, using the reward system. Children\'s self-control is still developing, so stopping feels like a real loss.','Clear limits, warning before transitions, real-life alternatives','Give a five-minute warning and a timer;Acknowledge the feeling: "It\'s hard to stop when you\'re winning.";Follow through calmly','Make a family media plan together;Keep devices out of bedrooms at night;Help them notice how they feel after too much screen time','Model healthy phone use yourself;Plan screen-free family times (meals, Sunday afternoon);Fill life with appealing alternatives: outdoors, friends, projects','"Five more minutes, then it\'s time to stop.";"I know it\'s hard. You can be upset and still turn it off.";"What would you like to do instead?"','Pulling the plug without warning;Using screens as the main reward or babysitter;Secretly spying instead of agreeing open rules','Ephesians 5:15-16|Therefore watch carefully how you walk… redeeming the time.','Psalm 90:12; 1 Corinthians 6:12; Philippians 4:8','Make a simple family screen plan together this week, including your own phone.','Games and videos are made to be hard to stop. Clear family rules, warnings before stopping and fun things to do instead make it easier.','loop','choices swap','Doomscrolling and phone urges;The Reward Loop: Dopamine & Habits'],
 ['homework','Homework Refusal','6–16','Refusal often hides tiredness, difficulty starting, fear of failing, or a learning difficulty, not laziness.','Help to start, a sense of competence','Snack and movement first;Sit nearby and help them start the first question;Break it into small chunks with short breaks','Ask: "Which part feels hardest?";Talk to the teacher if it\'s always a struggle;Praise effort and strategies','Same time and place each day;Watch for signs of learning difficulties or anxiety;Keep your love separate from their grades','"Let\'s just do the first one together.";"Mistakes help your brain grow.";"I\'m proud of how you kept going."','Doing it for them;Shouting or calling them lazy;Making your approval depend on marks','Colossians 3:23|Whatever you do, work heartily, as for the Lord.','Proverbs 1:5; Ecclesiastes 9:10; Philippians 4:13','Sit with your child for the first five minutes of homework tomorrow, then step back.','Homework can feel too big. Doing the first bit together and taking short breaks make it feel small enough to start.','road','start2 pomo','Procrastination;Fear of Making Mistakes'],
 ['backtalk','Back-Talk and Disrespect','6–18','Rudeness often comes from tiredness, feeling powerless, embarrassment, or copying how they are spoken to. Teens are also practising independence.','Respect, being heard, a voice','Stay calm; don\'t match their tone;Name the boundary: "I want to hear you. Please say it respectfully.";Take a break if you are both heated','Come back and listen to the real issue;Apologise if you were harsh too;Agree how disagreements will be handled in your family','Speak to them as you want them to speak to you;Give real choices and a voice in family decisions;Notice and thank respectful disagreement','"Try that again in a kinder voice, and I\'ll listen.";"You\'re allowed to disagree with me.";"Let\'s both take a break and talk in ten minutes."','Shouting back or sarcasm;Humiliating them, especially in public;Demanding instant obedience without listening','Proverbs 15:1|A gentle answer turns away wrath.','Ephesians 6:4; Colossians 4:6; James 1:19','When your child is rude this week, answer in a calm, quiet voice and set one clear boundary.','When children speak rudely, they are often tired or feeling small. If we stay calm and respectful, we show them how to disagree kindly.','light','kidrepair dearman','Assertive Communication'],
 ['anxiety','Anxious, Clingy or Fearful Children','2–18','Anxious children have a sensitive alarm system. Avoiding fears brings relief but makes the fear grow; reassurance alone does not teach them they can cope.','Safety plus confidence that they can cope','Stay calm and validate: "You\'re scared. That makes sense.";Express confidence: "I know you can do this, and I\'m here.";Breathe together slowly','Help them face fears in small steps (a fear ladder);Praise brave behaviour, not just outcomes;Teach that worries are "a false alarm" that can be talked back to','Keep routines predictable;Limit your own visible anxiety;Seek help if anxiety stops them going to school or doing normal things','"It\'s okay to feel scared. You can be scared and brave.";"What\'s the smallest brave step?";"Let\'s breathe like a balloon together."','Letting them avoid everything that scares them;Shaming fear ("Don\'t be silly");Over-reassuring endlessly','Joshua 1:9|Be strong and courageous. Don\'t be afraid… for the LORD your God is with you wherever you go.','Psalm 56:3; Isaiah 41:10; 2 Timothy 1:7','Choose one small brave step with your child this week and celebrate it.','Some children have a very loud worry alarm. We stay calm, tell them they can do hard things and help them take small brave steps.','ladder','ecoach ladder','The Anxiety Cycle;Anxious Avoidance'],
 ['teenwithdraw','Teen Withdrawal and Shutting You Out','12–18','Teens need privacy and peer time; some distance is healthy. But sudden or deep withdrawal can signal stress, bullying, depression or something they feel ashamed of.','Respect and a safe way back','Don\'t interrogate; offer low-pressure time (a drive, food, a walk);Say: "I\'m here whenever you want to talk.";Notice changes in sleep, eating, school, friends','Share something of your own day first;Ask open questions and listen without fixing;Respect their privacy, with agreed safety rules','Keep family rituals they can opt into (meals, outings);Stay interested in their world (music, games, friends);Seek help if there is hopelessness, self-harm or big changes','"I miss you. No pressure, I\'m just here.";"Want to grab food?";"Whatever it is, you won\'t lose my love."','Snooping as a first response;Criticising their friends or interests;Ignoring warning signs of depression or self-harm','Luke 15:20|While he was still far off, his father saw him, and was moved with compassion, and ran.','Isaiah 49:15; Hosea 11:4; Psalm 139:7-10','Invite your teen to one easy, side-by-side activity this week with no agenda.','Teenagers sometimes go quiet and want space. We keep the door open, spend easy time together and watch gently for signs they need help.','coreg','special kidrepair','Rejection Sensitivity;Loneliness'],
 ['losttemper','When I Lose My Temper With My Child','0–18','Your child\'s distress triggers your own alarm and often your own childhood memories. Tired, stressed parents have less of a "window". Losing it doesn\'t make you a bad parent; repair is what matters.','Repair, and calm for you','Stop and step away if you need to (child safe);Breathe out slowly; drop your shoulders;Say: "I need a minute to calm down."','Go back and repair: "I\'m sorry I yelled. That wasn\'t okay. It wasn\'t your fault.";Reconnect with a hug or time together;Then address the original problem calmly','Notice your triggers and your own HALT needs;Get support: rest, help, counselling for your own past;Plan what you\'ll do next time','"I\'m sorry I shouted. You didn\'t deserve that.";"Mummy/Daddy needs a calm-down breath too.";"Can we try that again?"','Blaming the child for your anger;Pretending it didn\'t happen;Endless guilt instead of repair','Psalm 103:8|The LORD is merciful and gracious, slow to anger, and abundant in loving kindness.','Lamentations 3:22-23; Ephesians 4:26,32; 1 John 1:9','Next time you lose it, come back within the hour and repair with your child.','Grown-ups get angry too. When we shout, we can say sorry and make it right. That teaches children that love is stronger than mistakes.','repair','kidrepair stop exhale','Snapping at people I love;Repair After a Conflict'],
 ['public','Meltdowns in Public','2–8','Shops, crowds and noise overload young nervous systems, especially when hungry or tired. Your embarrassment adds to your own alarm.','Calm, safety and a way out','Focus on your child, not the onlookers;Move somewhere quieter if you can;Stay close, say little, and wait it out','Talk about it later and plan for next time;Bring snacks and a comfort item;Keep outings short when they\'re tired','Prepare them before outings ("We\'re buying three things");Give them a job (holding the list);Leave early when you see signs of overload','"We\'re leaving now. I\'ll help you.";"It\'s too much in here. Let\'s find a quiet spot.";"You can be upset. I\'m staying with you."','Threats in public you can\'t keep;Shaming them to satisfy onlookers;Giving in to stop the scene','Psalm 46:1|God is our refuge and strength, a very present help in trouble.','Isaiah 41:10; Psalm 131:2; Galatians 6:2','Pack a "calm kit" (snack, water, small toy) for your next outing.','Busy shops can be too much for small children. Taking snacks, keeping trips short and staying calm when they get upset help a lot.','bucket','timein sensory','Noise and crowds are too much'],
 ['bullying','Bullying (Being Bullied or Bullying Others)','5–18','Bullied children often feel ashamed and hide it. Children who bully are often hurting, insecure, or copying what they see. Both need adults to act.','Protection, belonging, and accountability','If they tell you, stay calm and thank them;Believe them and make sure they are safe;Ask what they want to happen next','Work with the school, documenting incidents;Build their friendships and confidence outside school;If your child is bullying: stay calm, find out why, help them repair and change','Teach empathy and standing up for others;Keep communication about online life open;Watch for signs: avoiding school, lost belongings, mood changes','"Thank you for telling me. This is not your fault.";"We\'ll work this out together.";"What do you think made you want to hurt them?"','Telling them to "toughen up" or "just ignore it";Retaliating against the other child or family;Shaming a child who bullies without understanding why','Psalm 82:3|Defend the weak, the poor, and the fatherless. Maintain the rights of the poor and oppressed.','Proverbs 31:8-9; Micah 6:8; Matthew 18:6','Ask your child this week: "Is anyone being unkind at school or online?"','Bullying hurts children deeply. They need a grown-up who listens, believes them and acts to keep them safe. Children who bully need help to change, too.','fence','reach dearman','Fear of Judgment;Shame'],
 ['faithq','Faith Questions and Doubts','5–25','Questions are a sign of growing faith, not lost faith. Children and teens need to make faith their own, and fear-based answers can push them away.','Honesty, safety to question, a living example','Welcome the question: "That\'s a great question.";Say "I don\'t know" when you don\'t;Share how you have wrestled with it','Explore together: Bible, trusted books, a mentor;Point to Jesus, not just rules;Pray for them, and with them if they want','Let them see your faith in everyday life (Deuteronomy 6:7);Make church and family worship warm, not forced;Keep loving them whatever they decide','"I\'m glad you asked. Let\'s find out together.";"God isn\'t scared of your questions.";"Here\'s how I\'ve struggled with that too."','Shaming or panicking at doubts;Using God as a threat;Forcing faith with punishment','Mark 9:24|I believe. Help my unbelief!','Deuteronomy 6:6-9; Jude 1:22; 1 Peter 3:15','Ask your child or teen: "What\'s one question you have about God?" and explore it together.','Asking questions about God is a good thing. When we listen, answer honestly and show God\'s love, children can grow a faith of their own.','vine','blessing ecoach','Being Known and Loved;Identity as Beloved']
];
KP.forEach(([kid,t,ages,behind,need,now,later,long,say,dont,verse,more,action,simple,mm,tools,links])=>K({kind:'prob',kid,t,ages,behind,need,now,later,long,say,dont,verse,more,action,simple,mm,tools,links}));

// ---------- parenting practices ----------
P('connect','Connect Before You Correct','now','1–3 min','Calm and connect with your child before you teach or set a limit.',
'Notice your own state; breathe out slowly first;Get down to their eye level;Name what they feel: "You\'re really upset";Offer touch if they want it, or just stay close;When they are calmer, set the limit or teach the lesson in a few words',
'I don\'t have time => Even ten seconds of eye contact and a calm sentence helps;It feels like rewarding bad behaviour => Connection isn\'t permission; the limit still stands;My child pushes me away => Stay nearby and say "I\'m here when you\'re ready"',
'A calm, connected brain can learn; a flooded one can\'t. Connection brings the thinking brain back online (Siegel & Bryson, "connect and redirect").');
P('timein','Time-In: Calming Down Together','now','5–10 min','Instead of sending a child away to calm down, stay with them until they settle.',
'Move to a calm spot together (a cosy corner);Sit close and breathe slowly; let your calm be contagious;Name the feeling simply;Offer a calm-down tool: squeeze a pillow, blow bubbles, a drink of water;When calm, talk briefly about what happened and what to try next time',
'They hit or throw things => Keep everyone safe, move objects, stay calm and close;I\'m too angry myself => Take your own breath first, or tag in another adult;They\'re older => Offer space nearby: "I\'ll be in the kitchen when you\'re ready"',
'Children learn to regulate by being regulated with a calm adult (co-regulation). Isolation when upset can feel like rejection.');
P('special','Special Time','daily','10–15 min','Ten minutes of one-to-one, child-led play each day.',
'Name it: "This is our special time";Set a timer for 10–15 minutes;Let your child choose the activity (within reason);Follow their lead: describe, praise, enjoy; no correcting or teaching;End warmly: "I loved our special time. Same time tomorrow."',
'I have several children => Rotate days, or 5 minutes each;My teen won\'t play => Offer a drive, a snack run or their favourite show together;I get bored => Notice their face; this time fills their tank',
'Regular, predictable one-to-one attention reduces attention-seeking and defiance and strengthens attachment (parent–child interaction therapy).',{min:10});
P('ecoach','Emotion Coaching','daily','5 min','Help your child understand and handle feelings, in five steps.',
'Notice the feeling, especially when it is small;See it as a chance to connect and teach;Listen and validate: "That makes sense";Help them name it: "Are you feeling left out?";Set limits on behaviour and solve the problem together',
'It feels like I\'m encouraging drama => Naming feelings helps them settle faster;Some feelings scare me => Notice your own reaction first, and breathe;They won\'t talk => Try side-by-side activities, drawing or play',
'Children whose parents coach emotions have better self-control, friendships and school results (Gottman).');
P('kidrepair','Repair With Your Child','deep','5 min','Make things right after you have yelled, been unfair or lost connection.',
'Calm yourself first;Go to your child and get to their level;Own it simply: "I\'m sorry I yelled. That wasn\'t okay.";Make clear it wasn\'t their fault: "You didn\'t deserve that.";Reconnect: a hug, a game, time together;Later, solve the original problem calmly',
'I feel too ashamed => Repair is a strength; it teaches more than never failing;My child brushes it off => Say it anyway; it still lands;I do it every day => Get support for your own stress and triggers',
'Repair after rupture builds secure attachment; it\'s not perfection but repair that children need (Tronick).');
P('blessing','The Family Blessing','daily','1 min','Speak a short blessing over your child each day.',
'Choose a time: bedtime, the school run or a meal;Put a hand on their shoulder or head (if they like it);Speak a blessing, such as Numbers 6:24-26;Add one specific thing you love about them;Keep it short and warm, every day',
'They squirm or giggle => That\'s fine; keep it light and short;My teen is embarrassed => Write it in a note or text;I don\'t know what to say => Use the same verse every day',
'Hearing loving words from a parent shapes a child\'s inner voice and sense of identity. Blessing is one of the oldest ways families pass on faith.');
P('choices','Limited Choices and When-Then','now','1 min','Give your child some control within your limits.',
'Decide the non-negotiable (teeth must be brushed);Offer two acceptable choices: "Brush in the bathroom or the kitchen?";For tasks, use when-then: "When your shoes are on, then we can go to the park.";Follow through calmly',
'They choose neither => "If you don\'t choose, I\'ll choose for you";They argue => Repeat the choices calmly once, then follow through;It feels manipulative => It\'s respectful: real choices within real limits',
'Small, real choices meet a child\'s need for autonomy and reduce power struggles.');
Object.assign(PDESIGN,{
 connect:['When a child feels seen, their stress system settles and their thinking brain comes back online, so they can actually hear what you are teaching.','God draws near before He corrects. Jesus touched, ate with and welcomed people before He called them to change.','Isaiah 40:11|He will tend his flock like a shepherd. He will gather the lambs in his arm… and will gently lead those who have their young.','Mark 10:16; Hosea 11:4; Luke 19:5','Before your next correction, get down to eye level and name what your child feels.'],
 timein:['Children cannot calm themselves until they have been calmed many times by someone else. Time-in builds that ability; isolation can feel like rejection.','God does not send us away when we are upset; He stays. "I will never leave you" is the heart of secure attachment.','Hebrews 13:5|I will in no way leave you, neither will I in any way forsake you.','Psalm 34:18; Isaiah 43:2; Psalm 23:4','Set up a cosy calm-down corner and sit there with your child next time they are upset.'],
 special:['Predictable, undivided attention fills a child\'s "connection tank", which reduces attention-seeking behaviour.','God delights in each of His children individually. Special time is a small picture of His delight.','Zephaniah 3:17|He will rejoice over you with joy. He will calm you in his love. He will rejoice over you with singing.','Mark 10:13-16; Psalm 127:3; Psalm 149:4','Schedule ten minutes of special time with each child this week.'],
 ecoach:['Naming and accepting feelings calms the alarm and builds the thinking brain\'s control over emotions.','God listens to every emotion in the Psalms. He validates feelings and guides behaviour.','Romans 12:15|Rejoice with those who rejoice. Weep with those who weep.','Psalm 62:8; John 11:35; Ephesians 4:26','When your child shows a small feeling today, name it before it becomes a big one.'],
 kidrepair:['Repair after conflict teaches children that relationships survive mistakes, which is the foundation of secure attachment.','Every repair shows your child the gospel: wrong is named, forgiveness is offered, and love remains.','Ephesians 4:32|Be kind to one another, tender hearted, forgiving each other, just as God also in Christ forgave you.','James 5:16; Colossians 3:13; Matthew 5:23-24','Repair with your child within the hour after your next blow-up.'],
 blessing:['Words spoken repeatedly by a parent become a child\'s inner voice and shape their identity and resilience.','God blesses before He commands; His people received the blessing of Numbers 6 every day.','Numbers 6:24-26|The LORD bless you, and keep you. The LORD make his face to shine on you, and be gracious to you. The LORD lift up his face toward you, and give you peace.','Genesis 48:15-16; Mark 10:16; Proverbs 18:21','Speak Numbers 6:24-26 over your child at bedtime tonight.'],
 choices:['Choices meet the need for autonomy, which lowers resistance and builds decision-making skills.','God gives real choices and real responsibility, within loving boundaries, from the Garden onward.','Joshua 24:15|Choose today whom you will serve… but as for me and my house, we will serve the LORD.','Deuteronomy 30:19; Galatians 5:13; Proverbs 22:6','Turn one command into a choice of two today.']});
Object.assign(MM_P,{connect:'coreg',timein:'coreg',special:'battery',ecoach:'iceberg',kidrepair:'repair',blessing:'vine',choices:'fence'});

